draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character position
  let x = W / 2;
  let y = H / 2;

  // head
  ctx.beginPath();
  ctx.arc(x, y, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(x, y + 20);
  ctx.lineTo(x, y + 100);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(x, y + 40);
  ctx.lineTo(x - 30 + 20 * Math.sin(t), y + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x, y + 40);
  ctx.lineTo(x + 30 - 20 * Math.sin(t), y + 70);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(x, y + 100);
  ctx.lineTo(x - 20 + 10 * Math.sin(t), y + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x, y + 100);
  ctx.lineTo(x + 20 - 10 * Math.sin(t), y + 130);
  ctx.stroke();

  ctx.restore();
}
